public static void Run(){Directory.CreateDirectory(Out);Directory.CreateDirectory(Out+"/frames");var original=GameObject.Find("PlayerArmature");var preview=new PreviewRenderUtility();PlayableGraph graph=default;var report=new StringBuilder("Downloaded source FBX (verified against GLB) versus actual MyForest PlayerArmature. Same full clip, 0.5 playback speed. Root travel excluded equally to keep both skeletons in view. No head correction or locomotion layer.\n");
try{var player=UnityEngine.Object.Instantiate(original);player.transform.SetPositionAndRotation(new Vector3(-1.25f,0,0),Quaternion.identity);foreach(var b in player.GetComponentsInChildren<MonoBehaviour>())b.enabled=false;foreach(var c in player.GetComponentsInChildren<Collider>())c.enabled=false;preview.AddSingleGO(player);var pa=player.GetComponent<Animator>();pa.applyRootMotion=false;pa.cullingMode=AnimatorCullingMode.AlwaysAnimate;pa.Rebind();
var weapon=player.GetComponent<WeaponController>();var hand=pa.GetBoneTransform(HumanBodyBones.RightHand);var sword=UnityEngine.Object.Instantiate(weapon.SwordModelPrefab,hand,false);sword.transform.localScale=Vector3.one;const BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(WeaponController).GetField("animator",flags).SetValue(weapon,pa);typeof(WeaponController).GetField("sword",flags).SetValue(weapon,sword);var fit=typeof(WeaponController).GetMethod("FitGrip",flags);object[] args={sword,HumanBodyBones.RightHand,HumanBodyBones.RightIndexProximal,HumanBodyBones.RightLittleProximal,weapon.SwordGripOffset,weapon.SwordGripAdjustment};
graph=PlayableGraph.Create("Sword comparison idle grip");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var ctrl=AnimatorControllerPlayable.Create(graph,pa.runtimeAnimatorController);ctrl.SetBool("Grounded",true);ctrl.SetFloat("MotionSpeed",1);var output=AnimationPlayableOutput.Create(graph,"player",pa);output.SetSourcePlayable(ctrl);graph.Play();for(int i=0;i<60;i++)graph.Evaluate(1f/60);typeof(WeaponController).GetMethod("CalibrateStableSwordGrip",flags).Invoke(weapon,null);graph.Destroy();
preview.camera.transform.position=new Vector3(0,2.1f,8);preview.camera.transform.LookAt(new Vector3(0,1,0));preview.camera.fieldOfView=34;preview.camera.nearClipPlane=.05f;preview.camera.farClipPlane=40;preview.lights[0].intensity=2;preview.lights[0].transform.rotation=Quaternion.Euler(30,200,0);preview.lights[1].intensity=1.5f;int frame=0;float maxAngle=0;float sumAngle=0;int angles=0;
foreach(string name in new[]{"sword_regular_b","sword_regular_b_reversed","sword_regular_combo"}){
var path="Assets/ImportedSwordAnimations/Source/"+name+".fbx";var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));report.AppendLine("Source import rotation="+source.transform.localEulerAngles+" scale="+source.transform.localScale);source.transform.position=new Vector3(1.25f,0,0);source.transform.rotation=Quaternion.identity*source.transform.rotation;var sourceMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));sourceMat.color=new Color(.72f,.52f,.23f);foreach(var renderer in source.GetComponentsInChildren<Renderer>()){renderer.sharedMaterials=Enumerable.Repeat(sourceMat,Mathf.Max(1,renderer.sharedMaterials.Length)).ToArray();}preview.AddSingleGO(source);var sa=source.GetComponent<Animator>();sa.applyRootMotion=false;sa.cullingMode=AnimatorCullingMode.AlwaysAnimate;sa.Rebind();
if(name=="sword_regular_b"){report.AppendLine("Source avatar: "+sa.avatar.isValid+", human="+sa.avatar.isHuman+"; player avatar: "+pa.avatar.isValid+", human="+pa.avatar.isHuman);foreach(var bone in new[]{HumanBodyBones.Hips,HumanBodyBones.Spine,HumanBodyBones.Chest,HumanBodyBones.UpperChest,HumanBodyBones.Neck,HumanBodyBones.Head,HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm,HumanBodyBones.LeftHand,HumanBodyBones.RightUpperArm,HumanBodyBones.RightLowerArm,HumanBodyBones.RightHand,HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot,HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg,HumanBodyBones.RightFoot}){var a=sa.GetBoneTransform(bone);var b=pa.GetBoneTransform(bone);report.AppendLine(bone+": source="+(a?a.name:"MISSING")+" -> player="+(b?b.name:"MISSING"));}}
var clip=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>c.name==name+"_Full");graph=PlayableGraph.Create("Exact source vs target");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var sp=AnimationClipPlayable.Create(graph,clip);var pp=AnimationClipPlayable.Create(graph,clip);sp.SetApplyFootIK(false);pp.SetApplyFootIK(false);sp.SetSpeed(0);pp.SetSpeed(0);var so=AnimationPlayableOutput.Create(graph,"Source",sa);so.SetSourcePlayable(sp);var po=AnimationPlayableOutput.Create(graph,"Player",pa);po.SetSourcePlayable(pp);graph.Play();
int count=Mathf.CeilToInt(clip.length*2*24);report.AppendLine(name+": source length="+clip.length+"s, half speed="+(clip.length*2)+"s; output frames "+frame+".."+(frame+count-1));
for(int i=0;i<count;i++){double time=Math.Min(clip.length-.0001,i/48.0);sp.SetTime(time);pp.SetTime(time);graph.Evaluate(0);fit.Invoke(weapon,args);foreach(var pair in new[]{new[]{HumanBodyBones.Hips,HumanBodyBones.Head},new[]{HumanBodyBones.RightUpperArm,HumanBodyBones.RightLowerArm},new[]{HumanBodyBones.RightLowerArm,HumanBodyBones.RightHand},new[]{HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm},new[]{HumanBodyBones.LeftLowerArm,HumanBodyBones.LeftHand},new[]{HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg},new[]{HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot},new[]{HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg},new[]{HumanBodyBones.RightLowerLeg,HumanBodyBones.RightFoot}}){var sd=source.transform.InverseTransformDirection(sa.GetBoneTransform(pair[1]).position-sa.GetBoneTransform(pair[0]).position).normalized;var pd=player.transform.InverseTransformDirection(pa.GetBoneTransform(pair[1]).position-pa.GetBoneTransform(pair[0]).position).normalized;float a=Vector3.Angle(sd,pd);maxAngle=Mathf.Max(maxAngle,a);sumAngle+=a;angles++;}if(i==12){report.AppendLine("POSE source hips/head="+sa.GetBoneTransform(HumanBodyBones.Hips).position+" / "+sa.GetBoneTransform(HumanBodyBones.Head).position+"; player="+pa.GetBoneTransform(HumanBodyBones.Hips).position+" / "+pa.GetBoneTransform(HumanBodyBones.Head).position);foreach(var sk in source.GetComponentsInChildren<SkinnedMeshRenderer>()){var bm=new Mesh();sk.BakeMesh(bm);report.AppendLine("SOURCE MESH "+sk.name+" enabled="+sk.enabled+" scale="+sk.transform.lossyScale+" baked bounds="+bm.bounds+" world="+sk.bounds);UnityEngine.Object.DestroyImmediate(bm);}}Capture(preview,Out+"/frames/"+frame.ToString("D5")+".png",source,player);frame++;}
graph.Destroy();UnityEngine.Object.DestroyImmediate(source);}
report.AppendLine("Source to player limb direction difference: mean="+(sumAngle/Mathf.Max(1,angles))+" degrees, max="+maxAngle+" degrees; samples="+angles);File.WriteAllText(Out+"/skeleton-report.txt",report.ToString());File.WriteAllText(Out+"/done.txt",frame.ToString());Debug.Log("SWORD_RIG_COMPARISON_VIDEO_READY");
}finally{if(graph.IsValid())graph.Destroy();preview.Cleanup();}}
static Mesh WorldSkin(SkinnedMeshRenderer skin){var src=skin.sharedMesh;var vertices=src.vertices;var normals=src.normals;var weights=src.boneWeights;var binds=src.bindposes;var matrices=skin.bones.Select((b,i)=>b.localToWorldMatrix*binds[i]).ToArray();var result=new Vector3[vertices.Length];var ns=new Vector3[vertices.Length];for(int i=0;i<vertices.Length;i++){var w=weights[i];int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};for(int j=0;j<4;j++)if(ws[j]>0){result[i]+=matrices[ids[j]].MultiplyPoint3x4(vertices[i])*ws[j];if(normals.Length==vertices.Length)ns[i]+=matrices[ids[j]].MultiplyVector(normals[i])*ws[j];}ns[i].Normalize();}var mesh=UnityEngine.Object.Instantiate(src);mesh.vertices=result;if(normals.Length==vertices.Length)mesh.normals=ns;mesh.RecalculateBounds();return mesh;}
static void Capture(PreviewRenderUtility p,string path,params GameObject[] models){var temps=new System.Collections.Generic.List<GameObject>();var meshes=new System.Collections.Generic.List<Mesh>();var skins=models.SelectMany(m=>m.GetComponentsInChildren<SkinnedMeshRenderer>()).Where(s=>s.enabled).ToArray();var previous=RenderTexture.active;Texture2D image=null;try{foreach(var skin in skins){var mesh=WorldSkin(skin);meshes.Add(mesh);var go=new GameObject("Captured pose");p.AddSingleGO(go);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;temps.Add(go);skin.enabled=false;}p.BeginPreview(new Rect(0,0,960,540),GUIStyle.none);p.Render(true);var rt=p.EndPreview() as RenderTexture;RenderTexture.active=rt;image=new Texture2D(960,540,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,960,540),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=previous;if(image)UnityEngine.Object.DestroyImmediate(image);foreach(var x in temps)UnityEngine.Object.DestroyImmediate(x);foreach(var x in meshes)UnityEngine.Object.DestroyImmediate(x);foreach(var x in skins)if(x)x.enabled=true;}}
